descriptions.zh:
本接口与[BatchDeleteDcdnKv](~~BatchDeleteDcdnKv~~)的功能一样，只是允许上传更大请求体。当请求体较小时推荐直接使用[BatchDeleteDcdnKv](~~BatchDeleteDcdnKv~~)接口，从而减少服务端处理时间。本接口需要使用SDK进行调用。以golang SDK为例，需要使用BatchDeleteDcdnKvWithHighCapacityAdvance函数进行调用。
```
func TestBatchDeleteWithHighCapacity() error {
	// 配置初始化
	cfg := new(openapi.Config)
	cfg.SetAccessKeyId("xxxxxxxxx")
	cfg.SetAccessKeySecret("xxxxxxxxxx")
	cli, err := NewClient(cfg)
	if err != nil {
		return err
	}
	runtime := &util.RuntimeOptions{}

	// 构造待批量删除的键值对请求
	namespace := "test_batch_put"
	rawReq := BatchDeleteDcdnKvRequest{
		Namespace: &namespace,
	}
	for i := 0; i < 10000; i++ {
		key := fmt.Sprintf("test_key_%d", i)
		rawReq.Keys = append(rawReq.Keys, &key)
	}
	payload, err := json.Marshal(rawReq)
	if err != nil {
		return err
	}

	// 如果payload大于2M，则调用大容量接口进行删除
	reqHighCapacity := BatchDeleteDcdnKvWithHighCapacityAdvanceRequest{
		Namespace: &namespace,
		UrlObject: bytes.NewReader(payload),
	}
	resp, err := cli.BatchDeleteDcdnKvWithHighCapacityAdvance(&reqHighCapacity, runtime)
	if err != nil {
		return err
	}
	return nil
}

descriptions.en:
This operation provides the same features as [](t2701599.xdita#)but supports a larger request body. If your request body is small, use the [](t2701599.xdita#)operation to reduce server-side processing time. You must use an SDK to call this operation. For example, if you use the Go SDK, you must call the BatchDeleteDcdnKvWithHighCapacityAdvance function.

```
func TestBatchDeleteWithHighCapacity() error {
	// Initialize the configuration.
	cfg := new(openapi.Config)
	cfg.SetAccessKeyId("xxxxxxxxx")
	cfg.SetAccessKeySecret("xxxxxxxxxx")
	cli, err := NewClient(cfg)
	if err != nil {
		return err
	}
	runtime := &util.RuntimeOptions{}

	// Construct a request to batch delete key-value pairs.
	namespace := "test_batch_put"
	rawReq := BatchDeleteDcdnKvRequest{
		Namespace: &namespace,
	}
	for i := 0; i < 10000; i++ {
		key := fmt.Sprintf("test_key_%d", i)
		rawReq.Keys = append(rawReq.Keys, &key)
	}
	payload, err := json.Marshal(rawReq)
	if err != nil {
		return err
	}

	// If the payload is larger than 2 MB, call the high-capacity operation to delete the key-value pairs.
	reqHighCapacity := BatchDeleteDcdnKvWithHighCapacityAdvanceRequest{
		Namespace: &namespace,
		UrlObject: bytes.NewReader(payload),
	}
	resp, err := cli.BatchDeleteDcdnKvWithHighCapacityAdvance(&reqHighCapacity, runtime)
	if err != nil {
		return err
	}
	return nil
}
